desired = {"ingest-api": {"image": "v1.4.2", "replicas": 3},
           "label-worker": {"image": "v0.9.0", "replicas": 8}}
live = {"ingest-api": {"image": "v1.4.2", "replicas": 5},
        "label-worker": {"image": "v0.8.7", "replicas": 8},
        "debug-pod": {"image": "busybox", "replicas": 1}}
for name in sorted(desired.keys() | live.keys()):
    d, l = desired.get(name), live.get(name)
    if d == l:
        print(f"{name}: Synced")
    elif l is None:
        print(f"{name}: 없음 -> 만든다")
    elif d is None:
        print(f"{name}: Git 에 없음 -> 지운다(prune)")
    else:
        diff = {k: (l[k], d[k]) for k in d if d[k] != l.get(k)}
        print(f"{name}: OutOfSync {diff} -> Git 값으로 되돌린다")
# debug-pod: Git 에 없음 -> 지운다(prune)
# ingest-api: OutOfSync {'replicas': (5, 3)} -> Git 값으로 되돌린다
# label-worker: OutOfSync {'image': ('v0.8.7', 'v0.9.0')} -> Git 값으로 되돌린다
